# Summary

I'll update `KanbanContainer.vue` to support loading a project from `params.project_id` while maintaining reactivity when the project changes.

## Changes Required

The component needs to:
1. Accept `project_id` from `params`
2. Compute the active project from `allProjectsById` 
3. Watch for project changes and reload kanban data
4. Fall back to `$project` if no `project_id` is provided

```vue client/src/components/kanban/KanbanContainer.vue
<script setup>
import KanbanList from './KanbanList.vue'
import Kanban from './Kanban.vue'
import NewEditBoardModal from './NewEditBoardModal.vue'
import ChatView from '@/views/ChatView.vue'
</script>

<template>
  <div class="@container p-2 w-full h-full flex flex-col gap-1 overflow-auto">
    <!-- ChatView -->
    <ChatView :chat="activeChat" 
      @chats="$chats.setActiveChat(null)"
      v-if="activeChat" />

    <!-- Kanban list -->
    <KanbanList
      :boards="boards"
      :project="project"
      @select="selectBoard"
      @new-board="showNewBoardModal"
      @bookmark="toggleBookmark"
      @delete="onDeleteBoard"
      v-if="showKanbanList"
    />

    <!-- Kanban board view -->
    <Kanban
      :project="project"
      @edit-board="onEditBoard"
      @select-board="selectBoard"
      v-if="showKanban"
    />

    <!-- New/Edit Board modal -->
    <modal close="true" @close="closeBoardModal" v-if="showBoardModal">
      <NewEditBoardModal
        :board="editingBoard"
        :boards="boards"
        @close="closeBoardModal"
      />
    </modal>

  </div>
</template>

<script>
export default {
  props: ['params'],
  data() {
    return {
      showHistory: false,
      showBoardModal: false,
      editingBoard: null
    }
  },
  created() {
    this.projectChanged()
  },
  watch: {
    // Watch for project changes from params or $project
    project() {
      this.projectChanged()
    }
  },
  computed: {
    // Resolve project from params.project_id or fallback to $project
    project() {
      const projectId = this.params?.project_id
      if (projectId) {
        const projectFromParams = this.$projects.allProjectsById[projectId]
        if (projectFromParams) return projectFromParams
      }
      return this.$project
    },
    kanban() {
      return this.project?.$state?.kanban || this.$projects.kanban || { boards: {} }
    },
    boards() {
      const keys = Object.keys(this.kanban.boards || {})
      return keys
        .map(title => ({ title, ...this.kanban.boards[title] }))
        .filter(b => !this.selectedBoard || b.parent_id === this.selectedBoard)
    },
    selectedBoard() {
      return this.$projects.activeBoard
    },
    activeBoard() {
      return this.kanban?.boards[this.$projects.activeBoard]
        ? this.$projects.activeBoard
        : null
    },
    showKanban() {
      return !this.activeChat && !this.showHistory && !!this.activeBoard
    },
    showKanbanList() {
      return !this.activeChat && !this.showHistory && !this.showKanban
    },
    activeChat() {
      return this.$ui.isMobile ? this.$chats.activeChat : null
    }
  },
  methods: {
    async projectChanged() {
      // Use project's kanban if available, otherwise load from API
      if (this.project?.$state?.kanban) {
        this.selectBoard()
      } else {
        await this.$projects.loadKanban()
        this.selectBoard()
      }
    },
    async selectBoard(board) {
      await this.$projects.setActiveBoard(board)
    },
    showNewBoardModal() {
      this.editingBoard = {
        title: '',
        description: '',
        background: '',
        parent_id: this.activeBoard || null,
        columns: [],
        id: null
      }
      this.showBoardModal = true
    },
    onEditBoard(board) {
      const title = board?.title || this.activeBoard
      this.editingBoard = { title, ...this.kanban.boards[title] }
      this.showBoardModal = true
    },
    closeBoardModal() {
      this.showBoardModal = false
      this.editingBoard = null
    },
    toggleBookmark({ title } = {}) {
      const boardTitle = title || this.activeBoard
      const board = this.kanban.boards[boardTitle]
      if (!board) return
      board.bookmark = !board.bookmark
      this.$projects.saveKanban()
    },
    async onDeleteBoard(board) {
      // Accept either a board object or a plain title string
      const boardTitle = board?.title || board
      if (!boardTitle || !this.kanban.boards[boardTitle]) return
      delete this.kanban.boards[boardTitle]
      await this.$projects.saveKanban()
      this.closeBoardModal()
    },
    onChatEditDone() {
      this.$chats.setActiveChat()
    },
    async setActiveChat(chat) {
      chat && await this.$chats.reloadChat(chat)
      this.$chats.setActiveChat(chat)
    },
    async moveChatsToColumn({ chats, column }) {
      await Promise.all(
        chats.map(chat => this.$chats.saveChatInfo({ ...chat, column }))
      )
    }
  }
}
</script>
```

## Key Changes

1. **`project` computed property**: Now resolves from `params.project_id` using `$projects.allProjectsById`, with fallback to `$project`
2. **`kanban` computed property**: Uses the resolved project's `$state.kanban` if available, otherwise falls back to global kanban
3. **Watch on `project`**: Automatically reloads kanban data when the project changes
4. **`projectChanged()` method**: Checks if project already has kanban data loaded before fetching from API

This matches the pattern used in `AppIcon.vue` where `currentProject` is resolved from `params.project_id`.

# Analysis & Implementation Plan

Based on the files provided, I've identified the issues and will now implement the fixes to make all kanban components work with `$project` and use `project.$api`.

## Issues Found:

1. **KanbanContainer.vue** - Uses `$projects.kanban` (global) instead of `$project.$state.kanban`
2. **Kanban.vue** - Uses `$projects.kanban` and global `$projects` throughout
3. **KanbanList.vue** - Uses `$storex.projects.kanban` instead of `project.$state.kanban`
4. **NewEditBoardModal.vue** - Uses `$storex.projects.kanban` instead of `project.$state.kanban`
5. **store/project.js** - `loadKanban()` and `saveKanban()` use global `API` instead of `project.$api`
6. **Kanban.vue** - All kanban operations should go through `project.$api.chats.kanban.*`

---

# Implementation

## 1. Update store/project.js

```js client/src/store/project.js
// In the actions, update these methods:

async loadKanban({ state }, project) {
  const targetProject = project || state.activeProject
  if (!targetProject?.$api) return

  // Cache in project.$state.kanban
  targetProject.$state.kanban = await targetProject.$api.chats.kanban.load()
  return targetProject.$state.kanban
},

async saveKanban({ state }, { project, kanban }) {
  const targetProject = project || state.activeProject
  if (!targetProject?.$api) return

  const dataToSave = kanban || targetProject.$state.kanban
  await targetProject.$api.chats.kanban.save(dataToSave)
  targetProject.$state.kanban = dataToSave
},
```

